from fastapi import FastAPI
app = FastAPI()

@app.get('/')
def hello():
    return {'message': 'Hello, FastAPI'}
# 启动：uvicorn main:app --reload，然后打开 /docs

@app.get('/slow')
async def slow():
    await asyncio.sleep(1)   # 让出事件循环，不卡其它请求
    return {'ok': True}
# 反例：async 路由里写 time.sleep(1) 会卡住整个服务
